input.function:
() => {
  // Ищем все возможные поля ввода на странице
  const inputs = document.querySelectorAll('input, textarea');
  return Array.from(inputs).map(el => ({id: el.id, name: el.name, type: el.type, placeholder: el.placeholder, className: el.className, display: window.getComputedStyle(el).display, visibility: window.getComputedStyle(el).visibility})).filter(i => i.display !== 'none');
}

() => {
  const textarea = document.getElementById('b-checkform_qrraw');
  if (textarea) {
    // Очистить и ввести QR
    textarea.value = 't=20260727T2243&s=340.00&fn=7380440902999204&i=44046&fp=3573971155&n=1';
    textarea.dispatchEvent(new Event('input', { bubbles: true }));
    textarea.dispatchEvent(new Event('change', { bubbles: true }));
    return 'OK: value set to ' + textarea.value.length + ' chars';
  }
  return 'NOT FOUND';
}

() => {
  const btn = document.querySelector('.b-checkform_btn-send, button[type="submit"], button:contains("Проверить")');
  if (btn) return 'Found: ' + btn.className + ' disabled=' + btn.disabled;

  // Ищем все кнопки
  const btns = document.querySelectorAll('button');
  return Array.from(btns).map(b => ({text: b.textContent.trim(), id: b.id, class: b.className, disabled: b.disabled, type: b.type})).filter(b => b.disabled !== undefined);
}

() => {
  const btns = document.querySelectorAll('button');
  return Array.from(btns).map(b => ({text: b.textContent.trim().substring(0,30), id: b.id, class: b.className, disabled: b.disabled, type: b.type}));
}

() => {
  // Ввести QR в поле
  const ta = document.getElementById('b-checkform_qrraw');
  if (ta) {
    ta.value = 't=20260727T2243&s=340.00&fn=7380440902999204&i=44046&fp=3573971155&n=1';
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    ta.dispatchEvent(new Event('change', { bubbles: true }));
  }

  // Нажать кнопку "Проверить"
  const btn = document.querySelector('.b-checkform_btn-send');
  if (btn) {
    btn.scrollIntoView({block: 'center'});
    setTimeout(() => btn.click(), 500);
    return 'Clicked, value=' + ta.value.substring(0,30);
  }
  return 'Button not found';
}
